// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount && depositAmount > 0 && tx.origin != address(this));
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 bal_sender;
        try c.balances(address(this)) returns (uint256 __r) { bal_sender = __r; } catch { return; }
        uint256 bal_origin;
        try c.balances(tx.origin) returns (uint256 __r) { bal_origin = __r; } catch { return; }
        assertTrue(bal_sender >= depositAmount && bal_sender - depositAmount == 0 && bal_origin < bal_sender);
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable { }
}
